70:export async function checkPostingLive(
71:  url: string | null | undefined,
72:  opts: ProbeOptions = {},
73:): Promise<Liveness> {
74:  const id = postingIdentity(url);
75:  // No id, no board, or a family that cannot be asked — no request at all.
76:  // This is also what keeps a queue of a hundred postings from becoming a
77:  // hundred requests: most of them never reach the network.
78:  if (!id || id.family !== "greenhouse" || !id.board) return "unknown";
79:
80:  const job = await getJson(`${API}/${id.board}/jobs/${id.id}`, opts);
81:  if (!job) return "unknown"; // timeout, DNS, abort — never evidence of death
82:
83:  if (job.status === 200) {
84:    // A 200 whose body is not the posting we asked for is not a confirmation.
85:    const got = (job.body as { id?: unknown } | null)?.id;
86:    return got != null && String(got) === id.id ? "live" : "unknown";
87:  }
88:  if (job.status !== 404) return "unknown"; // 403, 429, 5xx — ask again later
89:
90:  // A 404 has two causes and they are indistinguishable from the body: the
91:  // posting is gone, or the BOARD SLUG IS WRONG. `boards/nao-existe-xyz/jobs/1`
92:  // returns the identical `{"status":404,"error":"Job not found"}`.
93:  //
94:  // That matters more than it looks. Reading a slug wrong — an API path parsed
95:  // as a company, a board renamed — would close every application on that board
96:  // as expired, at once, with evidence that reads convincingly. So the board is
97:  // confirmed to exist before the posting is declared gone. One extra request,
98:  // only on the rare path, in exchange for never mistaking a parsing bug for a
99:  // hundred dead jobs.
100:  const board = await getJson(`${API}/${id.board}`, opts);
101:  if (!board || board.status !== 200) return "unknown";
102:  return "dead";
103:}

